def solve(tokens):
    """Evaluate Reverse Polish Notation.
    tokens: list of strings, each token is an integer or one of '+', '-', '*', '/'.
    Return integer result, where division truncates toward zero.
    """
    stack = []
    ops = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: int(a / b)  # truncates toward zero
    }
    for tok in tokens:
        if tok in ops:
            b = stack.pop()
            a = stack.pop()
            stack.append(ops[tok](a, b))
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

