    """Simplify an absolute Unix path.
    Handles "." (current dir), ".." (parent dir), multiple slashes, and removes trailing slash.
    Returns '/' for the root. Empty input returns an empty string.
    """
    if path == "":
        return ""
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty components and current directory markers
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack is empty, stay at root (ignore further "..")
        else:
            stack.append(part)
    # Reconstruct the simplified path
    if not stack:
        return '/'  # root
    return '/' + '/'.join(stack)
"}

