def solve(path: str) -> str:
    """Simplify an absolute Unix path.

    The function resolves '.' (current directory) and '..' (parent directory),
    collapses multiple '/' characters, and removes any trailing slash. The
    result is always an absolute path; the root directory is returned as '/'.
    If the input is an empty string, it is treated as the root and '/' is
    returned.
    """
    # Treat empty input as root
    if not path:
        return '/'
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty components (caused by //) and current directory markers
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack is empty we stay at root, ignore extra '..'
        else:
            stack.append(part)
    # Reconstruct the simplified path
    return '/' + '/'.join(stack) if stack else '/'
}

