def solve(s: str) -> int:
    """Convert a Roman numeral to an integer.
    Handles standard symbols I, V, X, L, C, D, M and subtractive pairs.
    """
    value = {'I': 1, 'V': 5, 'X': 10, 'L': 50,
             'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s.upper()):
        cur = value[ch]
        if cur < prev:
            total -= cur
        else:
            total += cur
        prev = cur
    return total

