def solve(matrix):
    """Return determinant of integer square matrix. Empty matrix -> 1.
    Uses Bareiss algorithm for exact integer arithmetic.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Deep copy
    A = [list(row) for row in matrix]
    det_sign = 1
    prev = 1
    for k in range(n-1):
        # pivot
        if A[k][k] == 0:
            # find non-zero pivot below
            swap = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            A[k], A[swap] = A[swap], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j]) // prev
        prev = pivot
    return det_sign * A[n-1][n-1]

