def solve(grid):
    """Count islands in a binary grid, handling non‑rectangular rows.
    An island is a group of adjacent 1s (up, down, left, right).
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False]*len(row) for row in grid ]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if visited[i][j] or grid[i][j] != 1:
                continue
            visited[i][j] = True
            # neighbours
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    islands = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

