                    break
            else:
                return 0
        pivot = A[k][k]
        denom = A[k - 1][k - 1] if k > 0 else 1
        if denom == 0:
            return 0
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // denom
        for i in range(k + 1, n):
            A[i][k] = 0
    return det_sign * A[n - 1][n - 1]

