def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount* using unlimited coins.
    If impossible, return -1.
    Uses bottom‑up DP with O(amount * len(coins)) time.
    """
    # Edge case
    if amount == 0:
        return 0
    # Initialize DP array where dp[i] = min coins for amount i, sentinel large value.
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # If we can use coin c, consider dp[a - c] + 1
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

