def solve(n, edges):
    from heapq import heappush, heappop
    # Build adjacency list and indegree count
    adj = [[] for _ in range(n)]
    indeg = [0]*n
    for a,b in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    # Min-heap of nodes with zero indegree
    heap = []
    for i in range(n):
        if indeg[i] == 0:
            heappush(heap, i)
    order = []
    while heap:
        u = heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heappush(heap, v)
    if len(order) != n:
        return []
    return order

def solve(n):
    if n <= 2:
        return 0
    if n <= 3:
        return 1
    # odds-only sieve over odd numbers < n; index i represents number 2*i+1
    size = (n + 1) // 2
    sieve = bytearray([1]) * size
    sieve[0] = 0  # 1 is not prime
    i = 1
    while (2 * i + 1) * (2 * i + 1) < n:
        if sieve[i]:
            p = 2 * i + 1
            start = (p * p) // 2
            sieve[start::p] = bytearray(len(range(start, size, p)))
        i += 1
    return sum(sieve) + (1 if n > 2 else 0)

