def solve(grid):
    """Count islands in a possibly ragged grid (list of rows of varying lengths).
    Cells are 4-directionally connected (up, down, left, right) where the neighbor exists.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = [set() for _ in range(rows)]  # set of column indices visited per row

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if j in visited[i]:
                continue
            visited[i].add(j)
            # up
            if i > 0 and j < len(grid[i-1]) and grid[i-1][j] == 1 and j not in visited[i-1]:
                stack.append((i-1, j))
            # down
            if i + 1 < rows and j < len(grid[i+1]) and grid[i+1][j] == 1 and j not in visited[i+1]:
                stack.append((i+1, j))
            # left
            if j > 0 and grid[i][j-1] == 1 and (j-1) not in visited[i]:
                stack.append((i, j-1))
            # right
            if j + 1 < len(grid[i]) and grid[i][j+1] == 1 and (j+1) not in visited[i]:
                stack.append((i, j+1))

    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and j not in visited[i]:
                dfs(i, j)
                count += 1
    return count

